ATM_SFX_TRACK(sfxDown, ATM_VOL(36), ATM_SL_VOL((uint8_t)-6), ATM_NOTE_A5, ATM_DELAY(1), ATM_NOTE_E5, ATM_DELAY(2)); // one die less: down, 9 bytes (ch1)
