ATM_SFX_TRACK(sfxBack, ATM_VOL(38), ATM_SL_VOL((uint8_t)-4), ATM_NOTE_G5, ATM_DELAY(3), ATM_NOTE_C5, ATM_DELAY(6)); // back: falling pair, 9 bytes (ch1)
ATM_SFX_TRACK(sfxRoll, ATM_VOL(30), ATM_SL_VOL((uint8_t)-10), ATM_NOTE_C6, ATM_DELAY(2)); // dice rattle: tick, 7 bytes (ch1)
ATM_SFX_TRACK(sfxCoin, ATM_VOL(28), ATM_SL_VOL((uint8_t)-10), ATM_NOTE_E6, ATM_DELAY(1)); // coin spin: tick, 7 bytes (ch1)
ATM_SFX_TRACK(sfxLand, ATM_VOL(48), ATM_SL_VOL((uint8_t)-5), ATM_NOTE_G4, ATM_DELAY(1), ATM_NOTE_D4, ATM_DELAY(1), ATM_NOTE_G3, ATM_DELAY(3)); // dice land: thud, 11 bytes (ch1)
ATM_SFX_TRACK(sfxDing, ATM_VOL(40), ATM_SL_VOL((uint8_t)-3), ATM_NOTE_E6, ATM_DELAY(2), ATM_NOTE_B6, ATM_DELAY(4)); // result: ding, 9 bytes (ch1)
ATM_SFX_TRACK(sfxDing2, ATM_VOL(42), ATM_SL_VOL((uint8_t)-3), ATM_NOTE_C6, ATM_DELAY(2), ATM_NOTE_G6, ATM_DELAY(6)); // result shown: ding, 9 bytes (ch1)
ATM_SFX_TRACK(sfxCrit, ATM_VOL(48), ATM_SL_VOL((uint8_t)-2), ATM_NOTE_C5, ATM_DELAY(2), ATM_NOTE_E5, ATM_DELAY(2), ATM_NOTE_G5, ATM_DELAY(2), ATM_NOTE_C6, ATM_DELAY(2), ATM_NOTE_E6, ATM_DELAY(2), ATM_NOTE_G6, ATM_DELAY(10)); // natural 20: fanfare, 17 bytes (ch1)
